input.command:
sed -n 1,80p tests/test_migrations.py; .venv.mac/bin/python - <<'PY'
import alloq_commons.entities
import importlib, pkgutil
try:
    import appkit_user.authentication.backend.entities  # noqa
except Exception as e:
    print("no appkit_user entities", e)
from appkit_commons.database.entities import Base
for t in Base.metadata.sorted_tables:
    print("##", t.name)
    for c in t.columns:
        print("  ", c.name, c.type, "PK" if c.primary_key else "", "NULL" if c.nullable else "NN", "UQ" if c.unique else "", [f.target_fullname+":"+str(f.ondelete) for f in c.foreign_keys])
    for con in t.constraints:
        print("   con", type(con).__name__, getattr(con,'name',None), [c.name for c in getattr(con,'columns',[])])
PY

